this.code:
const obj = {
  name: 'Yo',
  greet() {
    return this.name;
  }
};

bind.code:
const user = { name: 'Alex' };
function say() { console.log(this.name); }
const sayAlex = say.bind(user);
sayAlex(); // 'Alex'

call.code:
function greet(lang) {
  console.log(`${lang}: ${this.name}`);
}
const user = { name: 'Bob' };
greet.call(user, 'ES'); // 'ES: Bob'

class.code:
class Rect {
  constructor(h, w) { this.h = h; this.w = w; }
  area() { return this.h * this.w; }
}

extends.code:
