destructuring.code:
const user = { id: 1, info: { name: 'F' } };
const { info: { name } } = user;
console.log(name); // 'F'

nullish.code:
const count = 0;
const qty = count || 10; // 10 (¡mal! 0 es válido)
const realQty = count ?? 10; // 0 (¡bien!)

rest.code:
function sum(...args) {
  return args.reduce((a, b) => a + b, 0);
}

generator.code:
function* count() { yield 1; yield 2; }
const it = count();
console.log(it.next().value); // 1

yield.code:
function* echo() {
  const input = yield 'Dime algo';
  console.log(input);
}

symbol.code:
const id = Symbol('id');
const obj = { [id]: 123 };
console.log(obj[id]); // 123

proxy.code:
const handler = { get: () => '404' };
const p = new Proxy({}, handler);
console.log(p.foo); // '404'
